<?php
namespace App\Services\Face;use App\Contracts\FaceProvider;use Aws\Rekognition\RekognitionClient;use RuntimeException;
class RekognitionFaceProvider implements FaceProvider {public function __construct(private RekognitionClient$client){}public function resolveCollection(string$key):string{try{$this->client->describeCollection(['CollectionId'=>$key]);}catch(\Throwable){$this->client->createCollection(['CollectionId'=>$key]);}return$key;}public function indexFace(string$c,string$external,string$bytes):array{$r=$this->client->indexFaces(['CollectionId'=>$c,'ExternalImageId'=>$external,'Image'=>['Bytes'=>$bytes],'MaxFaces'=>20,'QualityFilter'=>'AUTO']);$face=$r['FaceRecords'][0]['Face']??null;if(!$face)throw new RuntimeException('No indexable face detected.');return['face_id'=>(string)$face['FaceId'],'confidence'=>(float)($face['Confidence']??0)];}public function search(string$c,string$bytes,float$t,int$max):array{$r=$this->client->searchFacesByImage(['CollectionId'=>$c,'Image'=>['Bytes'=>$bytes],'FaceMatchThreshold'=>$t,'MaxFaces'=>$max]);return array_map(fn($m)=>['face_id'=>(string)$m['Face']['FaceId'],'external_id'=>(string)($m['Face']['ExternalImageId']??''),'similarity'=>(float)$m['Similarity']],$r['FaceMatches']??[]);}public function removeFaces(string$c,array$ids):void{if($ids)$this->client->deleteFaces(['CollectionId'=>$c,'FaceIds'=>array_values($ids)]);}public function deleteCollection(string$c):void{$this->client->deleteCollection(['CollectionId'=>$c]);}public function health():array{try{$this->client->listCollections(['MaxResults'=>1]);return['healthy'=>true,'provider'=>'rekognition'];}catch(\Throwable){return['healthy'=>false,'provider'=>'rekognition','error'=>'Provider unavailable.'];}}}
